import sys

# Increase recursion depth for deep trees
sys.setrecursionlimit(200000)

class Solution:
    def __init__(self):
        self.parent = []
        self.rank = []

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        px = self.find(x)
        py = self.find(y)
        if px != py:
            if self.rank[px] < self.rank[py]:
                px, py = py, px
            self.parent[py] = px
            if self.rank[px] == self.rank[py]:
                self.rank[px] += 1
            return True
        return False

    def solve(self, input_str):
        lines = input_str.strip().split('\n')
        if not lines:
            return ""

        n, m = map(int, lines[0].split())

        if m == n - 1:
            return ""

        edges = []
        for i in range(m):
            parts = lines[1 + i].split()
            u, v, w = int(parts[0]), int(parts[1]), int(parts[2])
            edges.append((u, v, w))

        # Sort edges by weight to find MST
        sorted_edges = sorted(edges, key=lambda x: x[2])

        # Find MST using Kruskal's algorithm
        self.parent = list(range(n + 1))
        self.rank = [0] * (n + 1)
        mst_edges = []

        for u, v, w in sorted_edges:
            if self.union(u, v):
                mst_edges.append((u, v, w))

        # Build adjacency list for MST
        adj = [[] for _ in range(n + 1)]
        for u, v, w in mst_edges:
            adj[u].append((v, w))
            adj[v].append((u, w))

        # DFS to compute depths and preprocess for LCA
        depth = [0] * (n + 1)
        dist = [[0] * 20 for _ in range(n + 1)]
        max_edge = [[0] * 20 for _ in range(n + 1)]

        def dfs(u, p, d, max_val):
            depth[u] = d
            dist[u][0] = p
            max_edge[u][0] = max_val
            for v, w in adj[u]:
                if v != p:
                    dfs(v, u, d + 1, max(max_val, w))

        dfs(1, 1, 0, 0)

        # Build binary lifting tables
        for j in range(1, 20):
            for i in range(1, n + 1):
                if dist[i][j - 1] != 0:
                    dist[i][j] = dist[dist[i][j - 1]][j - 1]
                    max_edge[i][j] = max(max_edge[i][j - 1], max_edge[dist[i][j - 1]][j - 1])
                else:
                    dist[i][j] = 0
                    max_edge[i][j] = max_edge[i][j - 1]

        def get_max_on_path(u, v):
            if depth[u] < depth[v]:
                u, v = v, u

            res = 0
            diff = depth[u] - depth[v]

            for j in range(20):
                if diff & (1 << j):
                    res = max(res, max_edge[u][j])
                    u = dist[u][j]

            if u == v:
                return res

            for j in range(19, -1, -1):
                if dist[u][j] != dist[v][j]:
                    res = max(res, max_edge[u][j])
                    res = max(res, max_edge[v][j])
                    u = dist[u][j]
                    v = dist[v][j]

            res = max(res, max_edge[u][0])
            res = max(res, max_edge[v][0])
            return res

        # Store original indices
        edges_with_idx = [(u, v, w, i) for i, (u, v, w) in enumerate(edges)]
        edges_with_idx.sort(key=lambda x: x[2])

        # Edges in MST
        mst_set = set()
        for u, v, w, idx in edges_with_idx:
            if self.union(u, v):
                mst_set.add(idx)

        # For non-MST edges, find max weight edge on path
        results = []
        for u, v, w, idx in edges_with_idx:
            if idx not in mst_set:
                max_on_path = get_max_on_path(u, v)
                # E_max is max_on_path - 1 (since weights must be distinct)
                # But problem says "largest e <= 10^9 such that the Daleks might use it"
                # With distinct weights, edge is used if it's lighter than heaviest in cycle
                results.append(str(max_on_path))

        return '\n'.join(results)

