    trie = [{'next': {}, 'fail': 0, 'end_patterns': []} for _ in range(1)]
    node_idx = 1

    def insert(pattern):
        node = 0
        for char in pattern:
            if char not in trie[node]['next']:
                trie.append({'next': {}, 'fail': 0, 'end_patterns': []})
                trie[node]['next'][char] = len(trie) - 1
            node = trie[node]['next'][char]
        trie[node]['end_patterns'].append(len(pattern))

    for p in patterns:
        insert(p)

    def build_failure():
        queue = deque()
        for char, child in trie[0]['next'].items():
            trie[child]['fail'] = 0
            queue.append(child)

        while queue:
            u = queue.popleft()
            for char, v in trie[u]['next'].items():
                f = trie[u]['fail']
                while f != 0 and char not in trie[f]['next']:
                    f = trie[f]['fail']
                if char in trie[f]['next']:
                    trie[v]['fail'] = trie[f]['next'][char]
                else:
                    trie[v]['fail'] = 0
                trie[v]['end_patterns'].extend(trie[trie[v]['fail']]['end_patterns'])
                queue.append(v)

    build_failure()

    states = []
    for i in range(len(trie)):
        states.append(0)

    max_state = len(trie)

    dp = [0] * max_state
    dp[0] = 1

    for pos in range(n):
        new_dp = [0] * max_state
        for state in range(max_state):
            if dp[state] == 0:
                continue

            for char in ['A', 'C', 'G', 'T']:
                nxt = trie[state]['next'][char]
                new_dp[nxt] = (new_dp[nxt] + dp[state]) % MOD

        dp = new_dp

    return str(sum(dp) % MOD) + '\n'

