def solution(input_str):
    from collections import deque

    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))

    # Check if sum of a equals sum of b
    if sum(a) != sum(b):
        return "NO"

    # Build adjacency list (0-indexed)
    adj = [[] for _ in range(n)]
    for i in range(m):
        p, q = map(int, lines[3 + i].split())
        adj[p-1].append(q-1)
        adj[q-1].append(p-1)

    # If no roads, check direct equality
    if m == 0:
        if all(a[i] == b[i] for i in range(n)):
            output_lines = ["YES"]
            for i in range(n):
                output_lines.append(" ".join(map(str, [a[i]] + [0 if j != i else 0 for j in range(n)])))
            return "\n".join(output_lines)
        else:
            return "NO"

    # Build flow network
    # Source = 0, Sink = n + 1, Cities = 1 to n
    capacity = [[0] * (n + 2) for _ in range(n + 2)]
    adj_list = [[] for _ in range(n + 2)]

    source, sink = 0, n + 1

    # Source to each city i with capacity a[i]
    for i in range(n):
        capacity[source][i + 1] = a[i]
        adj_list[source].append(i + 1)

    # Each city i can send to itself and neighbors
    for i in range(n):
        for j in range(n):
            if i == j or j in adj[i]:
                capacity[i + 1][j + 1] = 1000  # sufficient (max 100 soldiers)
                adj_list[i + 1].append(j + 1)

    # Each city j to sink with capacity b[j]
    for i in range(n):
        capacity[i + 1][sink] = b[i]
        adj_list[i + 1].append(sink)

    def bfs():
        visited = [False] * (n + 2)
        parent = [-1] * (n + 2)
        visited[source] = True
        queue = deque([source])

        while queue:
            u = queue.popleft()
            for v in adj_list[u]:
                if not visited[v] and capacity[u][v] > 0:
                    visited[v] = True
                    parent[v] = u
                    if v == sink:
                        return parent
                    queue.append(v)
        return [-1] * (n + 2)

    def dfs_flow(u, pushed, parent_array):
        if pushed == 0:
            return 0
        if u == sink:
            return pushed
        parent_check = parent_array.copy()

        # We need to track actual edges used for residual
        for v in adj_list[u]:
            if capacity[u][v] > 0 and not visited[v]:
                pushed = dfs_flow(v, min(pushed, capacity[u][v]))
                if pushed > 0:
                    capacity[u][v] -= pushed
                    capacity[v][u] += pushed
                    return pushed
        return 0

    def edmonds_karp():
        max_flow = 0
        while True:
            parent = bfs()
            if parent[sink] == -1:
                break
            # Find bottleneck
            path_flow = float('inf')
            curr = sink
            while curr != source:
                prev = parent[curr]
                path_flow = min(path_flow, capacity[prev][curr])
                curr = prev

            # Update residual capacities
            curr = sink
            while curr != source:
                prev = parent[curr]
                capacity[prev][curr] -= path_flow
                capacity[curr][prev] += path_flow
                curr = prev
            max_flow += path_flow
        return max_flow

    flow_result = edmonds_karp()

    if flow_result < sum(a):
        return "NO"

    # Reconstruct the movement matrix
    movement = [[0] * n for _ in range(n)]

    # For each city i, get flow from i to all neighbors/j
    for i in range(n):
        for j in range(n):
            if i == j or j in adj[i]:
                movement[i][j] = capacity[i + 1][j + 1]

    # Revert capacities to readable flow (since we modified them)
    # Actually, in residual graph, flow[i][j] = original_capacity[i][j] - capacity[i][j]
    # But since we set original to 1000 if allowed, we need different approach

    # Reconstruct from residual capacities correctly
    movement = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i == j or j in adj[i]:
                # Original capacity 1000, residual = 1000 - flow
                original_cap = 1000
                flow_ij = original_cap - capacity[i + 1][j + 1]
                movement[i][j] = flow_ij

    output_lines = ["YES"]
    for i in range(n):
        output_lines.append(" ".join(map(str, movement[i])))

    return "\n".join(output_lines)

from itertools import combinations

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    points = []
    for i in range(1, n + 1):
        x, y = map(int, lines[i].split())
        points.append((x, y))

    def triangle_area(a, b, c):
        """Absolute value of twice the triangle area"""
        return abs((b[0] - a[0]) * (c[1] - a[1]) - (c[0] - a[0]) * (b[1] - a[1]))

    def on_segment(p, a, b):
        """Check if point p lies on segment ab"""
        if triangle_area(p, a, b) == 0 and (min(a[0], b[0]) <= p[0] <= max(a[0], b[0]) and 
                                           min(a[1], b[1]) <= p[1] <= max(a[1], b[1])):
            return True
        return False

    def inside_triangle(p, a, b, c):
        """Check if point p is inside or on boundary of triangle abc"""
        # Check if p is on same line with any edge
        if triangle_area(p, a, b) == 0 and on_segment(p, a, b):
            return True
        if triangle_area(p, b, c) == 0 and on_segment(p, b, c):
            return True
        if triangle_area(p, a, c) == 0 and on_segment(p, a, c):
            return True
        return False

    def intersect_triangle(rt, t1, s1, s2):
        """Check if rectangle rt intersects with line segment s1-s2"""
        # Check if any endpoint inside rectangle
        rt_left, rt_right = rt[0], rt[1]
        rt_bottom, rt_top = rt[2], rt[3]
        inside = lambda p: rt_left <= p[0] <= rt_right and rt_bottom <= p[1] <= rt_top
        if inside(s1) or inside(s2):
            return True
        # Check all 4 edges of rectangle
        rect_edges = [(rt_left, rt_bottom), (rt_right, rt_bottom), 
                      (rt_right, rt_top), (rt_left, rt_top)]
        for i in range(4):
            if intersects(segment(line(rt_edges[i]), segment(s1, s2))):
                return True
        return False

    def intersects(a, b):
        """Check if two segments intersect (proper or improper)"""
        def ccw(p1, p2, p3):
            val = (p2[0] - p1[0]) * (p3[1] - p1[1]) - (p3[0] - p1[0]) * (p2[1] - p1[1])
            return 0 if val == 0 else (1 if val > 0 else -1)

        def on_segment(p, a, b):
            return min(a[0], b[0]) <= p[0] <= max(a[0], b[0]) and \
                   min(a[1], b[1]) <= p[1] <= max(a[1], b[1]) and \
                   triangle_area(p, a, b) == 0

        d1 = ccw(a[0], b[0], a[1], b[1])
        d2 = ccw(b[0], a[0], b[1], a[1])
        d3 = ccw(a[0], b[0], c[0], c[1])
        d4 = ccw(b[0], a[0], c[0], c[1])

        if d1 != d2 and d3 != d4:
            return True

        if d1 == 0 and on_segment(a[0], a[0], b[0]):
            return True
        if d2 == 0 and on_segment(b[0], a[0], b[0]):
            return True
        if d3 == 0 and on_segment(c[0], a[0], b[0]):
            return True
        if d4 == 0 and on_segment(c[0], a[0], b[0]):
            return True

        return False

    count = 0
    for six in combinations(range(n), 6):
        s_sext = list(six)
        for t1 in combinations(s_sext, 3):
            p1, p2, p3 = points[t1]
            if triangle_area(p1, p2, p3) == 0:
                continue
            rem = [x for x in s_sext if x not in t1]
            for t2 in combinations(rem, 3):
                q1, q2, q3 = points[t2]
                if triangle_area(q1, q2, q3) == 0:
                    continue
                # Check if triangles disjoint
                if not inside_triangle(p1, q1, q2, q3) and not inside_triangle(p2, q1, q2, q3) and not inside_triangle(p3, q1, q2, q3) and \
                   not inside_triangle(q1, p1, p2, p3) and not inside_triangle(q2, p1, p2, p3) and not inside_triangle(q3, p1, p2, p3):
                    # Check proper intersection
                    for (i, a), (j, b) in [(0,1,1,2), (0,1,1,3), (0,2,2,3), (1,2,2,3),
                                        (0,1,2,3), (0,2,1,3), (1,3,0,2), (2,3,0,1),
