    # - p = 2 (2 = 1² + 1², but note a,b must be positive)
    # - p ≡ 1 (mod 4) by Fermat's theorem on sums of squares
    # Note: a,b must be positive integers, so p = a² + b² with a,b >= 1
    # For p=2: 2 = 1² + 1² ✓ (a=1, b=1)

    # Sieve up to sqrt(r) to use for segmented sieve
    sqrt_r = int(r**0.5) + 1
    is_prime_small = [True] * (sqrt_r + 1)
    is_prime_small[0] = is_prime_small[1] = False

    for i in range(2, int(sqrt_r**0.5) + 2):
        if is_prime_small[i]:
            for j in range(i * i, sqrt_r + 1, i):
                is_prime_small[j] = False

    primes_small = [i for i, p in enumerate(is_prime_small) if p]

    count = 0
    segment_size = min(1000000, r - l + 1)

    start = l
    while start <= r:
        end = min(start + segment_size - 1, r)
        size = end - start + 1

        is_prime_segment = [True] * size

        for p in primes_small:
            if p * p > end:
                break

            # First multiple of p in [start, end]
            first = ((start + p - 1) // p) * p
            # Start from p*p for correctness in sieve
            first = max(first, p * p)

