def calc_f(x, y):
    if y == 0:
        return 0

    steps = 0
    while y > 0:
        g = math.gcd(x, y)
        if g == 0:
            break
        steps += 1
        y -= g
    return steps

def kmp_prefix_function(pattern):
    m = len(pattern)
    pi = [0] * m
    for i in range(1, m):
        j = pi[i-1]
        while j > 0 and pattern[i] != pattern[j]:
            j = pi[j-1]
        if pattern[i] == pattern[j]:
            j += 1
        pi[i] = j
    return pi

def transition(state, char, failure, pattern):
    j = state
    while j > 0 and pattern[j] != char:
        j = failure[j-1]
    if j < len(pattern) and pattern[j] == char:
        j += 1
    return j

