            if s[pos] != '?' and s[pos] != c:
                continue

            # Update balance for each character choice
            if c == 'W':
                new_balance = balance + 1
            elif c == 'L':
                new_balance = balance - 1
            else:  # D
                new_balance = balance

            # Valid paths must stay strictly within bounds until the end
            # The absolute balance must be < k at all positions before n
            if abs(new_balance) >= k:
                continue

            next_state = (pos + 1, new_balance)

            if next_state not in parent:
                parent[next_state] = (pos, balance, c)
                queue.append(next_state)

    # Find all valid end states at position n with |balance| == k
    end_states = []
    for (p, b) in parent:
        if p == n and abs(b) == k:
            end_states.append((p, b))

    if not end_states:
        return "NO"

    # Backtrack from the first valid end state
    target = end_states[0]
    result = []
    curr = target

    while curr is not None:
        prev_pos, prev_bal, ch = parent[curr]
        result.append(ch)
        curr = (prev_pos, prev_bal)

    return ''.join(result[::-1])

