    a = list(map(int, parts[1].split()))

    if n == 2 and a[0] == 1:
        return '-1'

    best = float('inf')

    for T in range(1, n+1):
        min_p = float('inf')

        left_blocked = [False] * n  # positions 0 to n-1
        right_blocked = [False] * n

        # Calculate blocking time for each icicle
        blocking_time = []
        for i in range(n):
            blocking_time.append(abs(i + 1 - T) + a[i])

        # Find earliest blocking on left and right
        for i in range(n-1):
            if blocking_time[i] < i + 1:
                left_blocked[i] = True

        for j in range(n-1, 0, -1):  # 1 to n-1 (position)
            if blocking_time[j-1] < j:
                right_blocked[j-1] = True

        for p in range(1, n):
            # Krakozyabra at position p at time p-1
            # Can Krakozyabra reach position p?
            can_reach = True
            for k in range(p):
                if blocking_time[k] == k:
                    can_reach = False
                    break
            if not can_reach:
                continue

            # Check if trapped at position p
            left_trapped = False
            right_trapped = False

            for i in range(p):
                if blocking_time[i] <= p-1:
                    left_trapped = True
                    break

            for j in range(p, n):
                if blocking_time[j] <= p-1:
                    right_trapped = True
                    break

            if left_trapped and right_trapped:
                best = min(best, p-1)

    return str(best) if best != float('inf') else '-1'

